from __future__ import annotations

from typing import Any


def format_mmss(seconds: float) -> str:
    sec = max(0, int(seconds or 0))
    return f"{sec // 60}:{sec % 60:02d}"


def clamp_pct(value: float, lo: float = 0.0, hi: float = 100.0) -> float:
    try:
        n = float(value)
    except (TypeError, ValueError):
        n = 0.0
    return max(lo, min(hi, n))


def scale_band(local_pct: float, lo: int, hi: int) -> int:
    """Map local 0–100 into overall [lo, hi]."""
    ratio = clamp_pct(local_pct) / 100.0
    return int(round(lo + (hi - lo) * ratio))


def _local_from_done_total(ev: dict[str, Any]) -> float | None:
    """Derive local percent from done/total when callers omit percent (llama MT)."""
    if ev.get("done") is None or ev.get("total") is None:
        return None
    try:
        done = float(ev["done"])
        total = float(ev["total"])
    except (TypeError, ValueError):
        return None
    if total <= 0:
        return None
    return clamp_pct(100.0 * done / total)


def remap_job_progress(task: str, event: dict[str, Any]) -> dict[str, Any]:
    """
    Normalize stage-local percents into a monotonic job-wide 1–100 scale.

    Bands (translate/dual):
      prep / audio prep         · 1–5
      ASR / extract source      · 5–65
      post-ASR source cleanup   · 62–65 (source_cleanup)
      MT load / translate start · 65–70 (translate local 0–8%)
      MT translate              · 70–95
      post-MT polish            · 95–98
      QC fix (UI per item)      · 98–100

    Bands (transcribe only):
      prep · 1–5, ASR · 5–92, polish · 92–98, finalize · 96–98
    """
    ev = dict(event or {})
    stage = str(ev.get("stage") or "").strip().lower()
    raw = clamp_pct(ev.get("percent") or 0)
    if raw <= 0:
        derived = _local_from_done_total(ev)
        if derived is not None:
            raw = derived
    has_mt = str(task or "").strip() in ("translate_mt", "dual", "translate")

    if stage in ("done", "batch_done"):
        overall = 100
    elif stage in ("error", "failed", "cancelled"):
        overall = int(raw) if raw > 0 else int(ev.get("percent") or 0)
    elif stage in ("starting", "queued"):
        overall = 1
    elif stage in ("preprocess", "denoise", "separate", "audio", "scene"):
        overall = scale_band(raw, 1, 5)
    elif stage in ("model", "vad", "vad_failover"):
        overall = scale_band(max(raw, 5.0), 2, 5)
    elif stage in ("asr_semantic_repair", "semantic_repair", "source_cleanup"):
        # End of extract-source band (before MT load 65–70).
        overall = scale_band(raw, 62, 65) if has_mt else scale_band(raw, 88, 92)
    elif stage in ("pip",):
        # Runtime extras while loading MT — stay in the translate-prep band.
        overall = scale_band(max(raw, 8.0), 65, 70) if has_mt else scale_band(max(raw, 8.0), 88, 92)
    elif stage in ("translate", "mt"):
        local = clamp_pct(raw)
        if has_mt and local <= 8.0:
            overall = scale_band((local / 8.0) * 100.0, 65, 70)
        elif has_mt:
            overall = scale_band(((local - 8.0) / 92.0) * 100.0, 70, 95)
        else:
            overall = scale_band(local, 70, 95)
    elif stage in ("cleanup",):
        overall = scale_band(raw, 95, 97) if has_mt else scale_band(raw, 92, 98)
    elif stage in ("save", "write"):
        overall = scale_band(raw, 97, 98)
    elif stage in ("qc_fix", "qc"):
        overall = scale_band(raw, 98, 100)
    elif stage in ("transcribe", "asr", "running", "asr-second-opinion"):
        lo, hi = (5, 65) if has_mt else (5, 92)
        overall = scale_band(raw, lo, hi)
    else:
        overall = int(raw)

    if stage not in ("done", "batch_done") and overall >= 100:
        overall = 99
    if overall < 1 and stage not in ("error", "failed", "cancelled"):
        overall = 1

    out = {**ev, "stage": stage or ev.get("stage"), "percent": int(overall)}
    # Keep timeline fields if present.
    for key in ("mediaDurationSec", "processedSec", "audioDurationSec"):
        if key in ev and ev[key] is not None:
            try:
                out[key] = float(ev[key])
            except (TypeError, ValueError):
                pass
    return out


def asr_local_from_timeline(*, processed_s: float, duration_s: float, start: float = 15.0, end: float = 92.0) -> float:
    """Convert audio timeline ratio into ASR-local percent."""
    dur = max(0.0, float(duration_s or 0))
    proc = max(0.0, float(processed_s or 0))
    if dur <= 0.5:
        return start
    ratio = min(0.99, proc / dur)
    return start + (end - start) * ratio
